/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Types: ImportCoverChoice
 *   Functions: embeddedImportOperationId, automaticCoverCleanupOperationId, isAutomaticCoverSlot,
 *              importAudioArtwork, importAlbumNotCreated, importAutomaticCover, importCoverChoice,
 *              chooseImportCover, replacedEmbeddedCandidateCleanable, automaticCoverCleanupCandidates
 * Internal
 *   Types: CoverSource
 *   Functions: isRecord, sha256, derivedUuid, assetsOf, skippedTrackSlots, cleanupReadiness
 *   Constants: PIN_RECHECK_MS
 * @end-catalog */

/**
 * Automatic embedded cover choice, and the candidates completion or a replaced file's staging cleans up. Pure; owner rules in
 * docs/business-rules.md (Administrator Album Imports, cover bullet). The choice is never stored: it is derived on every read, so a
 * changed file set re-evaluates it. Each audio upload records the image it carries at admission (`artworkSha256`); an upload
 * admitted before that has evidence only through its own per-file `embedded-<slotId>` candidate staged under the UUID derived from
 * its intent.
 */
import { createHash } from 'node:crypto';
import { ADMIN_IMPORT_LIMITS } from './adminImportContract';
import { hasOwn } from './adminImportDraft';
import { legacyManifestView } from './adminImportDraftCompat';
import { importUploadSettled, type ImportAsset, type ImportMedia } from './adminImportMediaTypes';
import type { AdminImportDocument } from './adminImportService';

/** An explicit choice is an administrator's (a slot or No cover); an automatic one is the shared embedded image or null. */
export type ImportCoverChoice = { mode: 'automatic' | 'explicit'; slotId: string | null };
type CoverSource = Pick<AdminImportDocument, 'manifest' | 'media' | 'decisions'>;
const isRecord = (value: unknown): value is Record<string, any> => Boolean(value) && typeof value === 'object' && !Array.isArray(value);
const sha256 = (value: unknown): value is string => typeof value === 'string' && /^[a-f0-9]{64}$/.test(value);
const derivedUuid = (value: unknown) => {
    const hash = createHash('sha256').update(JSON.stringify(value)).digest('hex');
    return `${hash.slice(0, 8)}-${hash.slice(8, 12)}-4${hash.slice(13, 16)}-8${hash.slice(17, 20)}-${hash.slice(20, 32)}`;
};
/** Frozen formula (v1 fixtures): the staging intent of the artwork embedded in one audio upload, so an audio replay stages nothing new. */
export const embeddedImportOperationId = (audioOperationId: string, audioSlotId: string) => derivedUuid({ operationId: audioOperationId, embedded: audioSlotId });
/** The cleanup intent completion reserves for one automatic candidate version; any current administrator retries with it. */
export const automaticCoverCleanupOperationId = (asset: Pick<ImportAsset, 'operationId' | 'slotId'>) => derivedUuid({ operationId: asset.operationId, automaticCleanup: asset.slotId });
export const isAutomaticCoverSlot = (slotId: unknown): slotId is string => typeof slotId === 'string' && slotId.startsWith('embedded-');
const assetsOf = (media: unknown): Record<string, any>[] => isRecord(media) && Array.isArray(media.assets) ? media.assets.filter(isRecord) : [];

/**
 * The embedded image one confirmed audio upload carries: its recorded SHA-256, null for none, or undefined when unknown (a
 * malformed record, or an upload admitted before admission recorded it whose own per-file candidate is missing).
 */
export function importAudioArtwork(assets: readonly unknown[], audio: Record<string, any>): string | null | undefined {
    if (hasOwn(audio, 'artworkSha256')) return audio.artworkSha256 === null || sha256(audio.artworkSha256) ? audio.artworkSha256 : undefined;
    if (typeof audio.operationId !== 'string' || typeof audio.slotId !== 'string') return undefined;
    const slotId = `embedded-${audio.slotId}`, operationId = embeddedImportOperationId(audio.operationId, audio.slotId);
    const candidate = assets.find(asset => isRecord(asset) && asset.slotId === slotId && asset.operationId === operationId) as Record<string, any> | undefined;
    return candidate && sha256(candidate.sha256) ? candidate.sha256 : undefined;
}
/** A saved Album decision other than create (reuse or skip, in either decision format); an undecided Album counts as create. */
export const importAlbumNotCreated = (decisions: unknown) => Array.isArray(decisions)
    && decisions.some(decision => isRecord(decision) && decision.scope === 'album' && (decision.action === 'reuse' || decision.action === 'skip'));
/** Files whose saved track decision is skip: they are published as no track, so their images never count. */
const skippedTrackSlots = (decisions: unknown) => new Set(Array.isArray(decisions)
    ? decisions.filter(decision => isRecord(decision) && decision.scope === 'track' && decision.action === 'skip').map(decision => decision.slotId) : []);

/**
 * The automatic cover: the ready `embedded-*` candidate, first in manifest order, of the one image every confirmed audio file
 * that becomes a track carries (a file whose saved track decision is skip does not count). Null when the Album is not created,
 * no such file is confirmed, one carries none, another image or unknown evidence, or that image has no ready candidate (bound
 * reached, staging unresolved or removed). Total on malformed records.
 */
export function importAutomaticCover(doc: CoverSource): string | null {
    if (importAlbumNotCreated(doc.decisions)) return null;
    const bySlot = new Map<unknown, Record<string, any>>(), skipped = skippedTrackSlots(doc.decisions); let shared: string | undefined;
    const assets = assetsOf(doc.media), files = legacyManifestView(doc.manifest).files;
    for (const asset of assets) if (!bySlot.has(asset.slotId)) bySlot.set(asset.slotId, asset);
    for (const file of files.filter(file => !skipped.has(file.slotId))) {
        const audio = bySlot.get(file.slotId); if (audio?.state !== 'ready') continue;
        const evidence = importAudioArtwork(assets, audio);
        if (typeof evidence !== 'string' || (shared !== undefined && evidence !== shared)) return null;
        shared = evidence;
    }
    if (shared === undefined) return null;
    // Any file's candidate may hold it, a skipped file's included: identical images are staged once.
    for (const file of files) {
        const candidate = bySlot.get(`embedded-${file.slotId}`);
        if (candidate?.state === 'ready' && candidate.sha256 === shared && typeof candidate.contentType === 'string' && candidate.contentType.startsWith('image/')) return candidate.slotId;
    }
    return null;
}
/**
 * A stored `selectedCoverSlotId` (from /select-cover, an approval or an earlier release) is explicit; a malformed one reads as No
 * cover. An automatic choice is derived, except that a publication not cancelled freezes the cover it showed (none for an append
 * or an approval that froze none), which the automatic choice then reads as.
 */
export function importCoverChoice(doc: CoverSource): ImportCoverChoice {
    const media = doc.media as unknown;
    if (isRecord(media) && hasOwn(media, 'selectedCoverSlotId')) return { mode: 'explicit', slotId: typeof media.selectedCoverSlotId === 'string' ? media.selectedCoverSlotId : null };
    const publication = isRecord(media) ? media.publication : undefined;
    if (isRecord(publication) && publication.state !== 'cancelled') return { mode: 'automatic', slotId: isRecord(publication.cover) && typeof publication.cover.slotId === 'string' ? publication.cover.slotId : null };
    return { mode: 'automatic', slotId: importAutomaticCover(doc) };
}
/** Records an explicit choice, which keeps the cover choice explicit for good. */
export const chooseImportCover = (media: ImportMedia, slotId: string | null) => { media.selectedCoverSlotId = slotId; };

/**
 * When an automatic candidate may be reserved for cleanup: now (true), once its transfer settles or its lease ends (that time),
 * or never (false: already cleaning or removed, or malformed). Pins are judged by the caller.
 */
function cleanupReadiness(asset: ImportAsset, now: Date): true | Date | false {
    if ((asset.recovery?.kind ?? 'upload') !== 'upload' || ['deleting', 'cleanupFailed', 'deleted'].includes(asset.state) || !(asset.updatedAt instanceof Date)) return false;
    const leased = Boolean(asset.leaseUntil && asset.leaseUntil > now);
    const settled = asset.state === 'ready' || (asset.state === 'failed' && Boolean(asset.failureConfirmedAt)) || importUploadSettled(asset, now);
    if (!leased && settled) return true;
    const deadline = asset.transferDeadline?.getTime() ?? asset.updatedAt.getTime() + ADMIN_IMPORT_LIMITS.uploadSettleMs;
    return new Date(Math.max(asset.leaseUntil?.getTime() ?? 0, deadline));
}

/**
 * Whether staging a replaced audio upload's own image may first clean up the candidate its slot still holds
 * (adminImportStorage.ts): one staged for an earlier intent of that slot, not explicitly chosen, unpinned, cleanable now, and
 * holding an image no other file's current upload carries, so no other file's evidence loses its candidate.
 */
export function replacedEmbeddedCandidateCleanable(doc: CoverSource, candidate: ImportAsset, audioSlotId: string, audioOperationId: string, now: Date): boolean {
    const media = doc.media as unknown, assets = assetsOf(media);
    if (candidate.slotId !== `embedded-${audioSlotId}` || candidate.operationId === embeddedImportOperationId(audioOperationId, audioSlotId) || candidate.coverConsumers?.length
        || (isRecord(media) && media.selectedCoverSlotId === candidate.slotId) || cleanupReadiness(candidate, now) !== true) return false;
    const current = (audio: Record<string, any>) => !['deleting', 'cleanupFailed', 'deleted'].includes(audio.state) && !(audio.state === 'failed' && audio.failureConfirmedAt);
    return !legacyManifestView(doc.manifest).files.some(file => file.slotId !== audioSlotId
        && assets.some(audio => audio.slotId === file.slotId && current(audio) && importAudioArtwork(assets, audio) === candidate.sha256));
}

/** How long a pinned candidate waits before the sweep checks it again: the existing-catalog cover grant lifetime. */
const PIN_RECHECK_MS = 24 * 3600_000;
/**
 * After completion: the automatic candidates to clean up, being neither the published cover, an explicit choice, pinned by an
 * existing-catalog cover operation, nor already cleaning or removed. An automatic choice is what the publication froze, so a
 * candidate it derives from the files but the publication never used is cleaned. A candidate whose transfer may still land waits,
 * and a pinned one is checked again a day later even if releasing its pin never re-arms the cleanup; `waitUntil` is the latest
 * such time.
 */
export function automaticCoverCleanupCandidates(doc: CoverSource, now: Date): { reserve: ImportAsset[]; waitUntil: Date | null } {
    const media = doc.media, reserve: ImportAsset[] = []; let waitUntil: Date | null = null;
    if (!isRecord(media) || media.publication?.state !== 'complete') return { reserve, waitUntil };
    const choice = importCoverChoice(doc), keep = new Set([media.publication.cover?.slotId, choice.mode === 'explicit' ? choice.slotId : undefined]);
    const wait = (until: Date) => { if (!waitUntil || until > waitUntil) waitUntil = until; };
    for (const asset of assetsOf(media) as ImportAsset[]) {
        if (!isAutomaticCoverSlot(asset.slotId) || keep.has(asset.slotId)) continue;
        const readiness = cleanupReadiness(asset, now); if (readiness === false) continue;
        if (asset.coverConsumers?.length) wait(new Date(now.getTime() + PIN_RECHECK_MS));
        else if (readiness === true) reserve.push(asset);
        else wait(readiness);
    }
    return { reserve, waitUntil };
}
